/* REBOOT20 — ChatGPT作。参考画像の構造だけを起点に、色・形・現象を別物として再設計。 */
window.Reboot20=function(canvas,index){
const ctx=canvas.getContext('2d');let W=0,H=0,D=1,phase=0,seed=Math.random()*9999,marks=[],active=null;
const N=['PRESS','BREATH','SHEAR','GRAVITY','DRIFT','FOLD','TRACE','MIRROR','SPLIT','FIELD','THREAD','GRAIN','RING','SCAR','TIDE','ORBIT','VOID','GATE','SWARM','FAULT'];
const P=[['#f2f2ed','#77756e'],['#d9c7a2','#4c453b'],['#9fc7c0','#334947'],['#e7b5b5','#583d3d'],['#c6d4ef','#454e65'],['#d5b4df','#4b3b52'],['#e9e0c5','#514d3f'],['#b8b8b8','#343434'],['#e6a56b','#593f2c'],['#c7d6b0','#414c35'],['#f0d7a5','#55452d'],['#b7c9cf','#38464a'],['#e2b7c9','#503d46'],['#d3c3ae','#4b443b'],['#a9c8b8','#354840'],['#c3c5dc','#45465d'],['#d6d1c6','#45423e'],['#f1b7a6','#563b36'],['#d8d2a4','#4b4930'],['#b9c8e5','#3f4a63']];
function resize(){D=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*D;canvas.height=H*D;ctx.setTransform(D,0,0,D,0,0)}addEventListener('resize',resize);resize();
function rnd(n){return Math.abs(Math.sin(n*12.9898+seed*78.233)*43758.5453)%1}
function dot(x,y,rx,ry,a,c,alpha=.7){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle=c;ctx.globalAlpha=alpha;ctx.beginPath();ctx.ellipse(0,0,Math.max(.45,rx),Math.max(.45,ry),0,0,Math.PI*2);ctx.fill();ctx.restore()}
function line(ps,c,a,w=1){ctx.beginPath();ps.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.strokeStyle=c;ctx.globalAlpha=a;ctx.lineWidth=w;ctx.stroke()}
function render(ph=phase){const S=Math.min(W,H),cx=W/2,cy=H/2,t=ph,[light,dark]=P[index%P.length];ctx.globalAlpha=1;ctx.fillStyle='#050505';ctx.fillRect(0,0,W,H);
if(index===0){for(let j=0;j<44;j++)for(let i=0;i<44;i++){let u=(i+.5*(j&1))/43-.5,v=j/43-.5,x=u*S*1.18+cx,y=v*S*1.18+cy;for(const m of marks){let dx=x-m.x,dy=y-m.y,r=Math.hypot(dx,dy)+1,q=Math.exp(-r*r/(S*S*.035));x+=dx*q*.34;y+=dy*q*.34}let z=Math.hypot(u,v),a=Math.atan2(v,u)+Math.sin(z*15-t*1.2)*.08;dot(x,y,2.8*(1-z*.55),1.4*(1-z*.2),a,light,.62)}}
else if(index===1){for(let r=0;r<38;r++){let rr=(r+1)/39*S*.62*(.86+.08*Math.sin(t+r*.16));for(let k=0;k<42;k++){let a=k/42*Math.PI*2+Math.sin(r*.8)*.08+t*.06,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr,s=1.2+r*.045;dot(x,y,s*1.9,s*.55,a,light,.58)}}for(const m of marks){ctx.fillStyle=dark;ctx.globalAlpha=.28;ctx.beginPath();ctx.arc(m.x,m.y,30+18*Math.sin(t*2),0,7);ctx.fill()}}
else if(index===2){for(let j=-34;j<=34;j++){let y=cy+j*S*.024,ps=[];for(let i=-40;i<=40;i++){let x=cx+i*S*.025,q=Math.sin(y*.018+t*.8)*S*.035;for(const m of marks){let d=Math.abs(y-m.y),f=Math.max(0,1-d/(S*.22));q+=(m.x-cx)*f*f*.18}ps.push([x+q,y+Math.sin(x*.02+t+j)*S*.004])}line(ps,j%3?dark:light,.5,.8)}}
else if(index===3){for(let r=0;r<30;r++)for(let k=0;k<48;k++){let rr=S*.045+r*S*.022,a=k/48*Math.PI*2+r*.04+t*(.08+r*.002),x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;for(const m of marks){let dx=m.x-x,dy=m.y-y,d=Math.hypot(dx,dy)+1,f=Math.min(.55,S*.12/d);x+=dx*f;y+=dy*f}dot(x,y,1.2+r*.055,1.2+r*.055,a,light,.62)}}
else if(index===4){for(let j=0;j<62;j++)for(let i=0;i<62;i++){let x=(i/61-.5)*S*1.3+cx,y=(j/61-.5)*S*1.3+cy,a=Math.sin(y*.017+t)*.9+Math.cos(x*.013-t*.7)*.7;for(const m of marks){let d=Math.hypot(x-m.x,y-m.y)+1,f=Math.max(0,1-d/(S*.24));a+=Math.atan2(m.y-y,m.x-x)*f*1.7}x+=Math.cos(a)*S*.035;y+=Math.sin(a)*S*.035;dot(x,y,1.4,3.8,a,light,.48)}}
else if(index===5){for(let j=-38;j<=38;j++)for(let i=-38;i<=38;i++){let x=cx+i*S*.023,y=cy+j*S*.023,q=Math.sin((x-y)*.025+t*.35);x+=Math.sign(q)*Math.min(S*.08,Math.abs(q)*S*.055);y+=Math.sin(x*.012+t)*S*.018;for(const m of marks){let d=Math.hypot(x-m.x,y-m.y);if(d<S*.2){let f=1-d/(S*.2),a=Math.atan2(y-m.y,x-m.x)+f*.9;x=m.x+Math.cos(a)*d;y=m.y+Math.sin(a)*d}}dot(x,y,3.4,.9,Math.atan2(y-cy,x-cx),light,.5)}}
else if(index===6){for(let q=0;q<marks.length;q++){let m=marks[q],ps=[];for(let i=0;i<150;i++){let z=i/149,x=m.x+(z-.5)*S*.85,y=m.y,a=Math.sin(z*9+q+t*1.2)*.7;x+=Math.cos(a)*S*.03;y+=Math.sin(a)*S*.03+Math.sin(z*5+t)*S*.08;ps.push([x,y])}line(ps,light,.6,1.2)}for(const m of marks)dot(m.x,m.y,6,6,0,light,.9)}
else if(index===7){let mx=marks[0]?.x??cx,my=marks[0]?.y??cy;for(let j=-26;j<=26;j++)for(let i=-26;i<=26;i++){let x=cx+i*S*.034,y=cy+j*S*.034,d=Math.hypot(x-cx,y-cy);if(d>S*.63)continue;let ang=Math.atan2(y-my,x-mx),ref=ang*2-(marks[1]?Math.atan2(marks[1].y-my,marks[1].x-mx):0),rr=Math.hypot(x-mx,y-my);dot(mx+Math.cos(ref)*rr,my+Math.sin(ref)*rr,2.5,1,ref,light,.55)}}
else if(index===8){for(let k=-22;k<=22;k++){let ps=[];for(let i=-30;i<=30;i++){let x=cx+i*S*.028,y=cy+k*S*.035+Math.sin(i*.23+t+k*.08)*S*.018;for(const m of marks){let d=Math.hypot(x-m.x,y-m.y);if(d<S*.18)y+=(k<0?-1:1)*(1-d/(S*.18))**2*S*.12}ps.push([x,y])}line(ps,k%4===0?light:dark,.65,1)}}
else if(index===9){for(let j=0;j<18;j++)for(let i=0;i<18;i++){let x=cx+(i/17-.5)*S*1.05,y=cy+(j/17-.5)*S*1.05,ax=Math.sin(y*.018+t),ay=Math.cos(x*.018-t);for(const m of marks){let d=Math.hypot(x-m.x,y-m.y)+1,f=Math.max(0,1-d/(S*.28));ax+=(x-m.x)/d*f*2;ay+=(y-m.y)/d*f*2}let a=Math.atan2(ay,ax);line([[x,y],[x+Math.cos(a)*12,y+Math.sin(a)*12]],light,.55,1.2)}}
else if(index===10){for(let k=0;k<34;k++){let ps=[];for(let i=0;i<190;i++){let u=i/189,x=(u-.5)*S*1.3+cx,y=cy+(k-16.5)*S*.025,yy=y+Math.sin(u*10+k*.7+t)*S*.025;for(const m of marks){let d=Math.hypot(x-m.x,yy-m.y)+1,f=Math.exp(-d*d/(S*S*.025));yy+=(m.y-yy)*f*1.7}ps.push([x,yy])}line(ps,k%5===0?light:dark,.46,k%5===0?1.2:.65)}}
else if(index===11){for(let j=0;j<74;j++)for(let i=0;i<74;i++){let x=cx+(i/73-.5)*S*1.15,y=cy+(j/73-.5)*S*1.15,a=Math.sin(x*.021+y*.014+t)+Math.cos(y*.027-t*.6);for(const m of marks){let d=Math.hypot(x-m.x,y-m.y);if(d<S*.18)a+=Math.atan2(y-m.y,x-m.x)*2*(1-d/(S*.18))}dot(x,y,1.1,5.5,a,light,.42)}}
else if(index===12){for(let r=0;r<28;r++){let rr=S*.06+r*S*.018,ps=[];for(let k=0;k<=180;k++){let a=k/180*Math.PI*2,rad=rr;for(const m of marks){let d=Math.hypot(cx+Math.cos(a)*rr-m.x,cy+Math.sin(a)*rr-m.y);rad+=Math.exp(-d*d/(S*S*.008))*S*.11*Math.sin(a*3+t)}ps.push([cx+Math.cos(a)*rad,cy+Math.sin(a)*rad])}line(ps,r%4===0?light:dark,.48,r===27?1.4:.7)}}
else if(index===13){for(let j=0;j<54;j++)for(let i=0;i<54;i++){let x=cx+(i/53-.5)*S*1.1,y=cy+(j/53-.5)*S*1.1,keep=true;for(const m of marks){let d=Math.abs((x-m.x)*Math.sin(m.a)+(y-m.y)*Math.cos(m.a));if(d<S*.012)keep=false}if(keep)dot(x,y,2.2,2.2,0,light,.38)}for(const m of marks)line([[m.x-Math.cos(m.a)*S,m.y+Math.sin(m.a)*S],[m.x+Math.cos(m.a)*S,m.y-Math.sin(m.a)*S]],light,.85,2)}
else if(index===14){for(let j=-32;j<=32;j++){let ps=[];for(let i=-38;i<=38;i++){let x=cx+i*S*.026,y=cy+j*S*.024,yy=y+Math.sin(x*.014+t*1.2+j*.2)*S*.028;for(const m of marks){let dx=x-m.x,dy=yy-m.y,d=Math.hypot(dx,dy)+1,f=Math.exp(-d*d/(S*S*.018));yy+=Math.sin(Math.atan2(dy,dx))*f*S*.12}ps.push([x,yy])}line(ps,j%6===0?light:dark,.5,j%6===0?1.5:.65)}}
else if(index===15){for(let k=0;k<18;k++){let rr=S*.08+k*S*.028,ps=[];for(let i=0;i<120;i++){let a=i/119*Math.PI*2+t*(.12+k*.003),ox=marks[0]?.x??cx,oy=marks[0]?.y??cy,x=ox+Math.cos(a)*rr,y=oy+Math.sin(a)*rr*.7;ps.push([x,y]);if(i%8===0)dot(x,y,2.5,1.2,a,light,.62)}line(ps,k%3===0?light:dark,.25,.6)}}
else if(index===16){for(let j=0;j<60;j++)for(let i=0;i<60;i++){let x=cx+(i/59-.5)*S*1.2,y=cy+(j/59-.5)*S*1.2,blocked=false;for(const m of marks){let d=Math.hypot(x-m.x,y-m.y);if(d<S*(.09+.025*Math.sin(t*2+m.a)))blocked=true}if(!blocked)dot(x,y,2.1,2.1,0,light,.45)}}
else if(index===17){let gx=marks[0]?.x??cx,gy=marks[0]?.y??cy;for(let j=-40;j<=40;j++)for(let i=-40;i<=40;i++){let x=cx+i*S*.022,y=cy+j*S*.022,d=Math.hypot(x-gx,y-gy),q=Math.max(0,1-d/(S*.18));x+=(cx-x)*q*.75;y+=(cy-y)*q*.75;dot(x,y,2.8*(1-q),1.1,Math.atan2(y-gy,x-gx),light,.5)}}
else if(index===18){for(let n=0;n<1300;n++){let q=rnd(n),r=Math.sqrt(q)*S*.68,a=rnd(n+4)*Math.PI*2+t*.08,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r,vx=-Math.sin(a),vy=Math.cos(a);for(const m of marks){let dx=m.x-x,dy=m.y-y,d=Math.hypot(dx,dy)+1,f=Math.min(.8,S*.16/d);vx+=dx*f;vy+=dy*f}dot(x,y,1.3,4.8,Math.atan2(vy,vx),light,.38)}}
else{for(let j=-30;j<=30;j++)for(let i=-30;i<=30;i++){let x=cx+i*S*.03,y=cy+j*S*.03,cut=Math.sin(x*.018+t)*S*.025;for(const m of marks){let d=Math.hypot(x-m.x,y-m.y);if(d<S*.16){let f=1-d/(S*.16);x+=Math.sin(j*.5)*f*S*.12;y+=Math.cos(i*.4)*f*S*.12}}if(Math.abs(y-cy-cut)<S*.018)continue;dot(x,y,2.2,1.4,(i+j)*.08,light,.48)}}}
function mutate(){seed=Math.random()*9999;marks=[];for(let i=0;i<1+(Math.random()*3|0);i++)marks.push({x:W*(.2+Math.random()*.6),y:H*(.2+Math.random()*.6),a:Math.random()*Math.PI*2})}
function reset(){marks=[];seed=Math.random()*9999}
function add(x,y){if(window.APKit&&APKit.isUI(x,y))return true;marks.push({x,y,a:Math.random()*Math.PI*2});if(marks.length>4)marks.shift();return true}
canvas.addEventListener('pointerdown',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;active={x:e.clientX,y:e.clientY};add(e.clientX,e.clientY)});
canvas.addEventListener('pointermove',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;if(active){active.x=e.clientX;active.y=e.clientY;const m=marks[marks.length-1];if(m){m.x=e.clientX;m.y=e.clientY}}});
canvas.addEventListener('pointerup',()=>active=null);canvas.addEventListener('pointercancel',()=>active=null);
function draw(){phase=(phase+.006)%(Math.PI*2);render();requestAnimationFrame(draw)}draw();mutate();
APKit.init({canvas:canvas,gifName:N[index]+'-loop',clockFormat:'spec',loopFrame:function(p){render(p)},buttons:[{label:'✦',name:'mutate',onClick:mutate},{label:'↻',name:'reset',onClick:reset}]});};
